      'Pemanfaatan senyawa kimia otak yang mengatur rasa senang untuk membuat pengguna terus terikat pada gawai.',
      'Upaya medis untuk menyembuhkan kecemasan sosial akibat terlalu sering melihat unggahan orang lain.',
      'Pembatasan akses konten negatif oleh sistem aplikasi guna menjaga kesehatan mental remaja.',
