    id: 802,
    question: `Jika Anda diminta menyusun sebuah bagan alur kerja teknologi Carbon Capture and Storage (CCS) berdasarkan informasi dalam teks Stimulus 1, urutan kerangka berpikir yang paling logis dan akurat adalah…`,
