    correctAnswer: 1, // B
    isHots: false,
    explanation: `Langkah Penyelesaian Persamaan Linear:
1. Buka kurung dengan sifat distributif perkalian:
   3(x - 2) = x + 8
   (3 × x) - (3 × 2) = x + 8
   3x - 6 = x + 8

2. Kumpulkan suku yang memiliki variabel x di ruas kiri dan angka di ruas kanan:
   3x - x = 8 + 6

3. Sederhanakan:
   2x = 14
   x = 14 ÷ 2
   x = 7.

Pembuktian: 3(7 - 2) = 3(5) = 15; dan 7 + 8 = 15 (Cocok!).

Kesimpulan: Nilai x yang memenuhi adalah 7 (Opsi B).`,
