    correctAnswer: 0, // A
    isHots: false,
    explanation: `Langkah Perkalian Aljabar Dua Suku (Metode FOIL / Depan, Luar, Dalam, Belakang):
(2x - 3)(x + 4)
1. Depan × Depan: 2x × x = 2x²
2. Depan × Belakang: 2x × (+4) = +8x
3. Belakang × Depan: -3 × x = -3x
4. Belakang × Belakang: -3 × (+4) = -12

Gabungkan semua suku:
= 2x² + 8x - 3x - 12

Sederhanakan suku-suku sejenis (+8x - 3x = +5x):
= 2x² + 5x - 12.

Kesimpulan: Bentuk sederhananya adalah 2x² + 5x - 12 (Opsi A).`,
