    id: 417,
    question: `Pada segitiga siku-siku ABC dengan siku-siku di B, ditarik garis tinggi BD ke sisi AC. Pernyataan rumus geometri yang benar berdasarkan kesebangunan pada segitiga tersebut adalah... (Pilih semua jawaban benar)`,
